  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    if not nodes:
        raise ValueError('Empty nodes list')
    node_by_id = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    retained = set(node_by_id.keys())
    removed_order = []
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if nid == 'root' or n['symbol'] in required_symbols:
            continue
        if not n['removable']:
            continue
        has_retained_child = any(child in retained for child in children.get(nid, []))
        if has_retained_child:
            continue
        retained.discard(nid)
        removed_order.append(nid)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed_order, 'retained_node_ids': retained_sorted}"
}
